#include "Core.hpp"
#include "PropertiesRequestDraft.hpp"
#include "FileInfoDecision.hpp"
#include "PublicationOwnership.hpp"
#include <iostream>
namespace udm {struct CatalogCheckpointTestAccess {static void observe(Manager& m,std::function<void(const char*)> f){Lock lock(m.mutex);m.catalogCheckpoint=std::move(f);}static void batch(Manager& m,bool v){Lock lock(m.mutex);m.catalogTransaction=v;}};}
using namespace udm;
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array(),cases=Json::array();std::string error,activeCase;
 const auto check=[&](bool good,const char* name){checks.push_back({{"name",name},{"passed",good}});if(!good)throw std::runtime_error(name);};
 try{for(const bool completed:{false,true})for(const std::string fault:{"none","removed","active","status","closing","origin","save","batch"}){
  if(!completed&&fault=="batch")continue;activeCase=(completed?"completed-":"unfinished-")+fault;Manager m(root/wide(activeCase)/L"catalog");const auto files=root/wide(activeCase)/L"files";fs::create_directories(files);auto prefs=m.state["Settings"];prefs["CategoryFolders"]=false;prefs["DownloadFolder"]=utf8(files.wstring());m.setSettings(prefs);auto job=m.add("https://fixture.example/source","","sample.bin","Main queue",true);if(completed){atomicText(job->target(),"verified bytes",false);job->data["Status"]="Complete";job->data["QueueMember"]=false;job->data["Size"]=14;job->data["Received"]=14;job->data["Sha256"]=fileHash(job->target());job->data["Finished"]=date();}const Headers before{{"Authorization","Bearer old"},{"Cookie","old=1"}},desired{{"Authorization","Bearer edited"},{"Cookie","old=1"}};PropertiesHeaderPatch patch(before,desired,str(job->data,"Url"));job->data["ProtectedHeaders"]=protect(legacyDictionary(Json(Headers{{"Authorization","Bearer fresh"},{"Cookie","fresh=1"}})).dump());m.save();
  std::unique_ptr<PublicationOwnership> owner;if(fault=="active")owner=std::make_unique<PublicationOwnership>(m,std::vector<JobPtr>{job},std::vector<fs::path>{job->target()});if(fault=="removed")m.jobs.clear();if(fault=="status")job->data["Status"]=completed?"Paused":"Complete";if(fault=="closing")m.stop();if(fault=="origin")job->data["Url"]="https://other-fixture.example/source";if(fault=="batch")CatalogCheckpointTestAccess::batch(m,true);const auto expected=job->snapshot();if(fault=="save")CatalogCheckpointTestAccess::observe(m,[](const char* point){if(std::string_view(point)=="temporary-flushed")throw std::runtime_error("Owned Properties catalog failure");});
  FileInfoDecisionTask task;task.startAction(m,[&m,job,patch,completed]{if(completed)m.configureCompletedProperties(job,{{"Description","worker description"}},patch);else m.configureProperties(job,{{"Description","worker description"}},patch);return FileInfoDecisionResult{};});bool failed=false;std::string message;try{task.get();}catch(const std::exception& e){failed=true;message=e.what();}task.release();CatalogCheckpointTestAccess::observe(m,{});CatalogCheckpointTestAccess::batch(m,false);check(failed==(fault!="none"),"The owned Properties command rejects stale, closed, active, cross-origin and failed-save inputs");check(!m.fileInfoDecisionPending,"Worker acknowledgement releases the decision owner after success or error");
  if(failed)check(job->snapshot()==expected,"Rejected Properties saves preserve the complete current job and request session");else{const auto headers=readHeaders(job->data);check(str(job->data,"Description")=="worker description"&&headerValue(headers,"Cookie")=="fresh=1"&&headerValue(headers,"Authorization")=="Bearer edited","The worker applies only the staged logical header delta to the current session");const auto saved=Json::parse(readText(m.root/L"state.json"));check(str(saved.at("Downloads").at(0),"Description")=="worker description","The worker completes the actual durable metadata save");}
  if(completed)check(fileHash(job->target())==str(expected,"Sha256"),"Properties metadata decisions preserve exact completed file bytes");owner.reset();if(fault=="removed")m.jobs.push_back(job);cases.push_back({{"completed",completed},{"fault",fault},{"error",message}});m.stop();
 }}catch(const std::exception& e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"error",error},{"case",activeCase},{"checks",checks},{"cases",cases}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;}
